update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"Hail, friend of nature! How may I help you?","cond":["druids only"],"alts":[{"cond":["knights only"],"reply":"Another creature who believes thinks physical strength is more important than wisdom! Why are you disturbing me?"},{"cond":["sorcerers only"],"reply":"It's good to see somebody who has chosen the path of wisdom. What do you want?"},{"cond":["paladins only"],"reply":"Neither strong enough to be a knight nor wise enough to be a real mage. You like it easy, don't you? Why are you disturbing me?"}]},{"say":"key","reply":"I will give the key to the crypt only to the closest followers of my master. Would you like me to test you?"},{"say":"yes","reply":"Before we start I must ask you for a small donation of 1000 gold coins. Are you willing to pay 1000 gold coins for the test?","alts":[{"other":true,"reply":"You're not worthy if you cannot make up your mind. Leave!","fx":["ends the conversation"]}]},{"say":"yes","reply":"All right then. Here comes the first question. What was the name of Dago's favourite pet?","fx":["takes 1000 gp"],"cond":["if you have 1000 gp"],"alts":[{"cond":["if you don't have 1000 gp"],"reply":"You don't even have the money to make a donation? Then go!","fx":["ends the conversation"]},{"other":true,"reply":"You're not worthy if you cannot make up your mind. Leave!","fx":["ends the conversation"]}]},{"say":"redips","reply":"Perhaps you knew him after all. Tell me - how many fingers did he have when he died?","alts":[{"other":true,"reply":"You are wrong. Get lost!","fx":["ends the conversation"]}]},{"say":"7","reply":"Also true. But can you also tell me the colour of the deamons in which master specialized?","alts":[{"other":true,"reply":"You are wrong. Get lost!","fx":["ends the conversation"]}]},{"say":"black","reply":"It seems you are worthy after all. Do you want the key to the crypt?","alts":[{"other":true,"reply":"You are wrong. Get lost!","fx":["ends the conversation"]}]},{"say":"yes","reply":"Here you are.","fx":["you get copper key (number 3142)"],"alts":[{"other":true,"reply":"It is always a wise decision to leave the dead alone."}]}]$j$::jsonb, updated_at = now()
