update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"Greetings, <your name>.","cond":["male characters only"],"alts":[{"cond":["female characters only"],"reply":"Greetings, <your name>. May I help you?"}]},{"say":"measurements","reply":"My measurements? Listen, lets make that a bit more exciting ... No, no, not what you think! I mean let's gamble. I will roll a dice. If I roll a 6 you win and I'll tell you what you need to know, else I win and get 5 gold. Deal?","cond":["quest 234 above 0","quest 240 below 1"]},{"say":"yes","reply":"Ok, here we go ... 6! You have won! How lucky you are! So listen ...<tells you what you need to know>","fx":["quest 234 becomes quest 234+1","quest 240 becomes 1"],"cond":["if you have 5 gp","random answer 6 (the NPC picks one)"],"alts":[{"other":true,"cond":["if you have 5 gp"],"reply":"Ok, and its ... <amount>! You have lost. He he. Another game?","fx":["takes 5 gp"]},{"other":true,"cond":["if you don't have 5 gp"],"reply":"I am sorry, but you don't have so much money."}]},{"say":"yes","reply":"Ok, no weights in the dice, no dirty tricks, are you ready?","alts":[{"other":true,"reply":"This way you'll never get my measurements."}],"cond":["after a lost game (\"Another game?\")"]},{"say":"yes","reply":"Ok, here we go ... 6! You have won! How lucky you are! So listen ...<tells you what you need to know>","fx":["quest 234 becomes quest 234+1","quest 240 becomes 1"],"cond":["if you have 5 gp","random answer 6 (the NPC picks one)"],"alts":[{"other":true,"cond":["if you have 5 gp"],"reply":"Ok, and its ... <amount>! You have lost. He he. Another game?","fx":["takes 5 gp"]},{"other":true,"cond":["if you don't have 5 gp"],"reply":"I am sorry, but you don't have so much money."}]}]$j$::jsonb, text = 'Ab''Dendriel, south-west of the depot: Olrik gambles for his measurements (5 gold per dice roll). If you lose, say "yes" twice to roll again (5 gold each time) until you roll a 6.', updated_at = now()
where id = 839 and updated_at = '2026-11-24T19:48:37.137414+00:00';

-- step 820 (The Postman Missions Quest): conditions/alternatives rebuilt from the corrected NPC data; one-bone-at-a-time route explained
update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"Do you bring ONE bone for our officers' safety fund or ALL bones at once?","cond":["quest 230 is 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers' safety fund?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 227 below 1"],"reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?"},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There's nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"all","reply":"Are you sure you have collected all the 20 bones needed?"},{"say":"yes","reply":"You have collected all the 20 bones needed. Excellent! Now let's talk about further missions if you are interested.","fx":["takes 20 bone","quest 230 becomes 21","quest 249 becomes 2"],"cond":["if you have 20 bone"],"alts":[{"other":true,"reply":"You have not enough bones with you. Too bad, but you surely will find some more."}]},{"say":"mission","reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?","cond":["quest 230 above 20"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers' safety fund?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 227 below 1"],"reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?"},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There's nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers' safety fund or ALL bones at once?"},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Your eagerness is a virtue, young one, but first lets talk about advancement.","cond":["quest 250 < quest 249"],"alts":[{"reply":"Since I am convinced I can trust you, this time you must deliver a valuable present to Dermot on Fibula. Do NOT open it!!! You will find the present behind the door here on the lower right side of this room.","fx":["quest 231 becomes 1"]},{"other":true,"reply":"Too bad, perhaps another time then."}]},{"say":"advancement","reply":"You are worthy indeed. Do you want to advance in our guild?","cond":["quest 250 < quest 249"],"alts":[{"cond":["quest 250 >= quest 249"],"reply":"Sorry, but you are not yet ready for advancement."}]},{"say":"yes","reply":"I grant you the title of postman. You are now a full member of our guild. Here have your own officers hat and wear it with pride.","fx":["quest 250 becomes 2","you get post officers hat"],"cond":["quest 249 is 2"],"alts":[{"cond":["quest 249 is 3"],"reply":"From now on it shall be known that you are a grand postman. You are now a privileged member until the end of days. Most captains around the world have an agreement with our guild to transport our privileged members, like you, for less gold.","fx":["quest 250 becomes 3"]},{"cond":["quest 249 is 4"],"reply":"From now on you are a grand postman for special operations. You are an honoured member of our guild and earned the privilege of your own post horn. Here, take it.","fx":["quest 250 becomes 4","you get post horn"]},{"cond":["quest 249 is 5"],"reply":"I grant you the title of archpostman. You are a legend in our guild. As privilege of your newly aquired status you are allowed to make use of certain mailboxes in dangerous areas. Just look out for them and you'll see.","fx":["quest 250 becomes 5"]}]}]$j$::jsonb, text = 'Tell Kevin you completed the mission and brought all the bones, then ask about advancement. You are now a Postman (post officer''s hat). Can''t carry all 20? Say "one" instead of "all": he takes one bone; after that say "mission" and "yes" for every further bone (one at a time, 20 in all). Once you''ve given one bone, "all" is no longer offered.', updated_at = now()
where id = 820 and updated_at = '2026-11-24T19:48:37.137414+00:00';

-- step 825 (The Postman Missions Quest): conditions/alternatives rebuilt from the corrected NPC data
update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"Be greeted, <your name>!"},{"say":"uniform","reply":"A new uniform for the post officers? I am sorry but my dog ate the last dress pattern we used. You need to supply us with a new dress pattern.","cond":["quest 233 is 1"],"alts":[{"reply":"I don't get it, what uniforms you are talking about."}]},{"say":"dress pattern","reply":"It was ... wonderous beyond wildest imaginations! I have no clue where Kevin Postner got it from. Better ask him.","fx":["quest 233 becomes 2"],"cond":["quest 233 is 1"],"alts":[{"cond":["quest 233 above 1","quest 233 below 9"],"reply":"I already told you to ask your boss about that issue."},{"cond":["quest 233 is 9"],"reply":"By the gods of fashion! Didn't it do that I fed the last dress pattern to my poor dog? Will this mocking of all which is taste and fashion never stop?? Ok, ok, you will get those ugly, stinking uniforms and now get lost, fashion terrorist.","fx":["quest 233 becomes 10","ends the conversation"]}]}]$j$::jsonb, updated_at = now()
where id = 825 and updated_at = '2026-11-24T19:48:37.137414+00:00';

-- step 840 (The Postman Missions Quest): conditions/alternatives rebuilt from the corrected NPC data
update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"Hiho <your name>. May I help you?"},{"say":"measurements","reply":"Come on, I have no clue what they are. Better ask my armorer Kroox for such nonsense. Go and ask him for good ol' Lokurs measurements, he'll know.","fx":["quest 235 becomes 1"],"cond":["quest 234 above 0"],"alts":[{"cond":["quest 235 above 0"],"reply":"Ask Kroox about that stuff."}]}]$j$::jsonb, updated_at = now()
where id = 840 and updated_at = '2026-11-24T19:48:37.137414+00:00';

