-- step 854 (The Postman Missions Quest): conditions/alternatives rebuilt from the corrected NPC data; warning: bye before the letter burns you
update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"No! The hornless have reached my city! BODYGUARDS TO ME!","fx":["quest 222 becomes 1","summons a minotaur guard","summons a minotaur guard","summons a minotaur mage","summons a minotaur mage","summons a minotaur archer","summons a minotaur archer","summons a minotaur archer","ends the conversation"],"cond":["quest 222 is 0"],"alts":[{"cond":["quest 245 is 2"],"reply":"Oh, it's you again. What do you want, hornless messenger?"},{"reply":"Well ... you defeated my guards! Now everything is over! I guess I will have to answer your questions now."}]},{"say":"hi","reply":"Well ... you defeated my guards! Now everything is over! I guess I will have to answer your questions now.","alts":[{"cond":["quest 222 is 0"],"reply":"No! The hornless have reached my city! BODYGUARDS TO ME!","fx":["quest 222 becomes 1","summons a minotaur guard","summons a minotaur guard","summons a minotaur mage","summons a minotaur mage","summons a minotaur archer","summons a minotaur archer","summons a minotaur archer","ends the conversation"]},{"cond":["quest 245 is 2"],"reply":"Oh, it's you again. What do you want, hornless messenger?"}]},{"say":"letter","reply":"A letter from my Moohmy?? Do you have a letter from my Moohmy to me?","cond":["quest 245 is 1"]},{"say":"yes","reply":"Uhm, well thank you, hornless beeing.","fx":["quest 245 becomes 2","takes letter to Markwin"],"cond":["if you have letter to Markwin"],"alts":[{"reply":"Don't mock the king of the minotaurs or you will regret that!"},{"other":true,"reply":"Uh? What??"}]}]$j$::jsonb, text = 'Say hi to Markwin (invisible or with a stealth ring; or from outside the castle to lure the guards a few at a time), then hi again and give him the letter. Don''t say "bye" to Markwin before he has the letter: he sets you on fire.', updated_at = now()
where id = 854 and updated_at = '2026-11-24T19:48:37.137414+00:00';

