-- step 828 (The Postman Missions Quest): conditions/alternatives rebuilt from the corrected NPC data
update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"dress pattern","reply":"The mail with Talphion's instructions just arrived. I remember we asked Queen Eloise of Carlin for the perfect colours. Go there, ask her about the UNIFORMS and report back here.","fx":["quest 233 becomes 5"],"cond":["quest 233 is 4"],"alts":[{"cond":["quest 233 is 8"],"reply":"Fine, fine. I think that should do it. Tell Hugo that we order those uniforms. The completed dress pattern will soon arrive in Venore. Report to me when you have talked to him.","fx":["quest 233 becomes 9"]},{"cond":["quest 233 is 6"],"reply":"The queen has sent me the samples we needed. The next part is tricky. We need the uniforms to emanate some odor that dogs hate.The dog with the best 'taste' in that field is Noodles, the dog of King Tibianus. Do you understand so far?"},{"cond":["quest 233 is 2"],"reply":"Oh yes, where did we get that from ...? Let's see, first ask the great technomancer in Kazordoon for the technical details. Return here afterwards.","fx":["quest 233 becomes 3"]}]}]$j$::jsonb, updated_at = now()
where id = 828 and updated_at = '2026-11-24T19:48:37.137414+00:00';

-- step 843 (The Postman Missions Quest): conditions/alternatives rebuilt from the corrected NPC data
update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"Be greeted, noble <your name>."},{"say":"measurements","reply":"Oh no! I knew that day would come! I am slightly above the allowed weight and if you can't supply me with some grapes to slim down I will get fired. Do you happen to have some grapes with you?","cond":["quest 234 above 0","quest 238 below 1"]},{"say":"yes","reply":"Oh thank you! Thank you so much! So listen ... <whispers her measurements>","fx":["takes grapes","quest 234 becomes quest 234+1","quest 238 becomes 1"],"cond":["if you have grapes"],"alts":[{"reply":"Don't tease me! You don't have any."},{"other":true,"reply":"Oh, no! I might loose my job."}]}]$j$::jsonb, updated_at = now()
where id = 843 and updated_at = '2026-11-24T19:48:37.137414+00:00';

-- step 855 (The Postman Missions Quest): conditions/alternatives rebuilt from the corrected NPC data
update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"],"cond":["quest 245 is 2"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers' safety fund?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 227 below 1"],"reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?"},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There's nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers' safety fund or ALL bones at once?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"advancement","reply":"You are worthy indeed. Do you want to advance in our guild?","cond":["quest 250 < quest 249"],"alts":[{"cond":["quest 250 >= quest 249"],"reply":"Sorry, but you are not yet ready for advancement."}]},{"say":"yes","reply":"I grant you the title of archpostman. You are a legend in our guild. As privilege of your newly aquired status you are allowed to make use of certain mailboxes in dangerous areas. Just look out for them and you'll see.","fx":["quest 250 becomes 5"],"cond":["quest 249 is 5"],"alts":[{"cond":["quest 249 is 2"],"reply":"I grant you the title of postman. You are now a full member of our guild. Here have your own officers hat and wear it with pride.","fx":["quest 250 becomes 2","you get post officers hat"]},{"cond":["quest 249 is 3"],"reply":"From now on it shall be known that you are a grand postman. You are now a privileged member until the end of days. Most captains around the world have an agreement with our guild to transport our privileged members, like you, for less gold.","fx":["quest 250 becomes 3"]},{"cond":["quest 249 is 4"],"reply":"From now on you are a grand postman for special operations. You are an honoured member of our guild and earned the privilege of your own post horn. Here, take it.","fx":["quest 250 becomes 4","you get post horn"]}]},{"say":"bye","reply":"Good bye.","fx":["ends the conversation"]}]$j$::jsonb, updated_at = now()
where id = 855 and updated_at = '2026-11-24T19:48:37.137414+00:00';

-- step 829 (The Postman Missions Quest): conditions/alternatives rebuilt from the corrected NPC data
update public.map_quest_steps set dialog = $j$[{"say":"hail queen","reply":"I greet thee, my loyal subject."},{"say":"uniform","reply":"I remember about those uniforms, they had a camouflage inlay so they could be worn the inside out too. I will send some colorsamples via mail to Mr. Postner.","fx":["quest 233 becomes 6"],"cond":["quest 233 is 5"],"alts":[{"reply":"The uniforms of our guards and soldiers are of unparraleled quality of course."}]}]$j$::jsonb, updated_at = now()
where id = 829 and updated_at = '2026-11-24T19:48:37.137414+00:00';

