-- step 834 (The Postman Missions Quest): conditions/alternatives rebuilt from the corrected NPC data
update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"Be greeted, <your name>!"},{"say":"dress pattern","reply":"By the gods of fashion! Didn't it do that I fed the last dress pattern to my poor dog? Will this mocking of all which is taste and fashion never stop?? Ok, ok, you will get those ugly, stinking uniforms and now get lost, fashion terrorist.","fx":["quest 233 becomes 10","ends the conversation"],"cond":["quest 233 is 9"],"alts":[{"cond":["quest 233 above 1","quest 233 below 9"],"reply":"I already told you to ask your boss about that issue."},{"cond":["quest 233 is 1"],"reply":"It was ... wonderous beyond wildest imaginations! I have no clue where Kevin Postner got it from. Better ask him.","fx":["quest 233 becomes 2"]}]}]$j$::jsonb, updated_at = now()
