update public.map_quest_steps set dialog = $j$[{"say":"hi","reply":"Be greeted, traveler.","alts":[{"cond":["quest 220 above 0","quest 62 is 2"],"reply":"Sorry my friend, the monks don't allow me to talk to you because of your intrusion in their chambers. Unless you plea to the abbot for absolution I can do nothing for you.","fx":["ends the conversation"]},{"cond":["quest 220 above 0"],"reply":"The monks forbid me to talk to you for you evil deeds.","fx":["ends the conversation"]}]},{"say":"brooch","reply":"What? You want me to examine a brooch?","alts":[{"cond":["quest 62 is 2"],"reply":"You have recovered my brooch! I shall forever be in your debt, my friend!"}]},{"say":"yes","reply":"Can it be? I recognize my family's arms! You have found a treasure indeed! I am poor and all I can offer you is my friendship, but ... please ... give that brooch to me?","cond":["if you have family brooch"],"alts":[{"cond":["if you don't have family brooch"],"reply":"What are you talking about? I am too poor to be interested in jewelry."},{"other":true,"reply":"Then stop being a fool. I am poor and I have to work the whole day through!"}]},{"say":"yes","reply":"Thank you! I shall consider you my friend from now on! Just let me know if you need something!","fx":["takes family brooch","quest 62 becomes 2"],"cond":["if you have family brooch"],"alts":[{"reply":"I should have known better then to ask for an act of kindness in this cruel, selfish, world!"},{"other":true,"reply":"I should have known better then to ask for an act of kindness in this cruel, selfish, world!"}]}]$j$::jsonb, updated_at = now()
