-- step 810: trips only count in this order
update public.map_quest_steps set text = 'Check the postal routes by travelling them: boat Thais to Carlin (110 gp), walk to the Femor Hills and take the carpet to Edron (60 gp), boat to Venore (40 gp), walk to Kazordoon and take the steam boat in the deepest cave to Cormaya (160 gp). Then back to Kevin (cheapest: through the rotworm caves to Edron, boat to Venore, walk). Only these four trips in exactly this order count; any other route doesn''t.', updated_at = now()
where id = 810 and updated_at = '2026-11-24T19:34:46.605378+00:00';

-- step 678: level 20 gate
update public.map_quest_steps set text = 'Go through the level 20 gate into the vocation room (everyone needs level 20). In the vocation room each puts the item on their basin, then steps on the tile in front of it: knight south, paladin north, druid west, sorcerer east. When all four are on their tiles, the paladin pulls the lever in front of him: all four are teleported to the reward room.', updated_at = now()
where id = 678 and updated_at = '2026-11-23T06:31:28.099977+00:00';

