select 89, 136, 25, 'talk', 'Captain Jack', 'Back to the continent with Captain Jack (20 gold). He drops you at the fisherman''s house where Dalbrect lives, not in Carlin. ("passage" only gets you a hint: say "continent".)', $j$[{"say":"hi","reply":"By the gods! You must be that intruder the good brothers were talking about! Begone!","fx":["ends the conversation"],"cond":["quest 220 above 0"],"alts":[{"reply":"Ahoy, matey. You are lucky to catch me here. I was preparing to set sail."}]},{"say":"continent","reply":"Friends of Dalbrect are my friends too! So you are looking for a passage to the continent for 20 gold?","cond":["quest 62 is 2"],"alts":[{"cond":["quest 62 is 1"],"reply":"Do you want a passage to the continent for 20 gold?"},{"cond":["quest 62 below 1"],"reply":"Without the abbots permission I won't take sail you anywhere! Go and ask him for a passage first."}]},{"say":"yes","reply":"Have a nice trip!","fx":["takes 20 gp","ends the conversation","teleports you to 32205, 31756, 7"],"cond":["if you have 20 gp"],"alts":[{"reply":"You don't have enough money."},{"other":true,"reply":"Well, I'll be here if you change your mind."}]}]$j$::jsonb, '[]'::jsonb, false, 'dialog review 2026-11-25'
